//! Embedded, bounded voice clips. No disk reads or allocation during playback.
pub use crate::sound_model::Event;
pub fn clip(event: Event) -> &'static [u8] {
    // Canonical WAV header generated by tools/prepare_sounds.py: mono s16, 16 kHz.
    let wav: &'static [u8] = match event {
        Event::Startup => include_bytes!("../assets/sounds/startup.wav"),
        Event::Shutdown => include_bytes!("../assets/sounds/shutdown.wav"),
        Event::Error => include_bytes!("../assets/sounds/error.wav"),
        Event::Warning => include_bytes!("../assets/sounds/warning.wav"),
        Event::Info => include_bytes!("../assets/sounds/info.wav"),
        Event::Complete => include_bytes!("../assets/sounds/complete.wav"),
        Event::Connect => include_bytes!("../assets/sounds/connect.wav"),
        Event::Disconnect => include_bytes!("../assets/sounds/disconnect.wav"),
        Event::Empty => include_bytes!("../assets/sounds/empty.wav"),
    };
    &wav[44..]
}
pub fn play(event: Event) {
    crate::audio::system_sound(event);
}
pub fn load() {
    let mut data = [0; 8];
    if let Ok(8) = crate::diskfs::read_at("/SOUND.CFG", 0, &mut data) {
        if &data[..4] == b"SND1" {
            let n = u32::from_le_bytes(data[4..].try_into().unwrap());
            if n <= 100 {
                crate::audio::system_volume(Some(n));
            }
        }
    }
}
pub fn command(argument: &str) {
    let mut words = argument.split_whitespace();
    match (words.next(), words.next(), words.next()) {
        (None, None, None) | (Some("list"), None, None) => {
            crate::println!(
                "System sounds volume: {}% (0 is mute; separate from Player)",
                crate::audio::system_volume(None)
            );
            crate::println!("sounds test NAME | sounds volume 0..100 | sounds mute | sounds unmute | sounds save");
            crate::println!("startup shutdown error warning info notification complete connect disconnect empty");
        }
        (Some("test"), Some(name), None) => {
            if let Some(event) = Event::parse(name) {
                play(event);
            } else {
                crate::println!("Unknown sound name.");
            }
        }
        (Some("volume"), Some(value), None) => match value.parse::<u32>() {
            Ok(n) if n <= 100 => {
                crate::audio::system_volume(Some(n));
            }
            _ => crate::println!("Volume must be 0..100."),
        },
        (Some("mute"), None, None) => {
            crate::audio::system_volume(Some(0));
        }
        (Some("unmute"), None, None) => {
            crate::audio::system_volume(Some(60));
        }
        (Some("save"), None, None) => {
            let mut data = [0; 8];
            data[..4].copy_from_slice(b"SND1");
            data[4..].copy_from_slice(&crate::audio::system_volume(None).to_le_bytes());
            let result = match crate::diskfs::create("/SOUND.CFG") {
                Ok(()) | Err(crate::fat16::Error::Exists) => {
                    crate::diskfs::write("/SOUND.CFG", &data)
                }
                Err(e) => Err(e),
            };
            match result {
                Ok(_) => crate::println!("System sound volume saved."),
                Err(e) => crate::println!("Sound settings: {}", e.message()),
            }
        }
        _ => crate::println!("Usage: sounds [list|test NAME|volume 0..100|mute|unmute|save]"),
    }
}
pub fn syscall(op: u32, a: u32, b: u32) -> u32 {
    if b != 0 {
        return (-22i32) as u32;
    }
    match op {
        0 => match Event::from_id(a) {
            Some(event) => {
                play(event);
                0
            }
            None => (-22i32) as u32,
        },
        1 if a == 0 => crate::audio::system_volume(None),
        2 if a <= 100 => {
            crate::audio::system_volume(Some(a));
            0
        }
        _ => (-22i32) as u32,
    }
}
